import { describe, expect, it } from "vitest";
import { createApp, type App } from "../src/app.ts";

const fixedClock = () => new Date("2026-10-01T08:00:00Z");

function setup(): App {
  return createApp({ clock: fixedClock });
}

/** Creates a coupon and asserts it was accepted. */
function createCoupon(app: App, coupon: Record<string, unknown>): void {
  const res = app.request("POST", "/coupons", {
    validFrom: "2026-01-01T00:00:00Z",
    validUntil: "2027-01-01T00:00:00Z",
    ...coupon,
  });
  expect(res.status).toBe(201);
}

function createOrder(app: App, amountCents: number): number {
  const res = app.request("POST", "/orders", { customer: "alice", amountCents });
  expect(res.status).toBe(201);
  return (res.body as { id: number }).id;
}

describe("apply coupon - validation", () => {
  it("rejects an unknown coupon with 400", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "NOPE" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_NOT_FOUND");
  });

  it("rejects a disabled coupon with 400", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "OFF", type: "FIXED", value: 1000, status: "DISABLED" });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "OFF" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_INACTIVE");
  });

  it("rejects an expired coupon with 400", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "OLD", type: "FIXED", value: 1000, validUntil: "2026-09-01T00:00:00Z" });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "OLD" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_EXPIRED");
  });

  it("rejects a coupon that is not yet valid with 400", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "SOON", type: "FIXED", value: 1000, validFrom: "2026-11-01T00:00:00Z" });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SOON" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_NOT_YET_VALID");
  });

  it("rejects an order below the minimum amount with 400", () => {
    const app = setup();
    const id = createOrder(app, 3000);
    createCoupon(app, { code: "BIG", type: "FIXED", value: 1000, minAmountCents: 5000 });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "BIG" });
    expect(res.status).toBe(400);
    expect((res.body as any).error.code).toBe("COUPON_MIN_AMOUNT");
  });

  it("rejects a missing coupon code with 400", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    expect(app.request("POST", `/orders/${id}/apply-coupon`, {}).status).toBe(400);
  });

  it("returns 404 for an unknown order", () => {
    const app = setup();
    const res = app.request("POST", "/orders/99/apply-coupon", { couponCode: "SAVE20" });
    expect(res.status).toBe(404);
    expect((res.body as any).error.code).toBe("ORDER_NOT_FOUND");
  });

  it("leaves the order unchanged when the coupon is rejected", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "NOPE" });
    const order = app.request("GET", `/orders/${id}`).body as any;
    expect(order).toMatchObject({ discountCents: 0, finalAmountCents: 12000, couponCode: null });
  });
});

describe("apply coupon - discount", () => {
  it("applies a FIXED coupon and returns 200 with the updated order", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "SAVE20", type: "FIXED", value: 2000 });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      amountCents: 12000,
      discountCents: 2000,
      finalAmountCents: 10000,
      couponCode: "SAVE20",
    });
  });

  it("applies a PERCENT coupon", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "P20", type: "PERCENT", value: 20 });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "P20" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 2400, finalAmountCents: 9600, couponCode: "P20" });
  });

  it("caps a PERCENT discount at maxDiscountCents", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "CAP", type: "PERCENT", value: 50, maxDiscountCents: 1000 });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "CAP" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 1000, finalAmountCents: 11000 });
  });

  it("never discounts more than the order amount", () => {
    const app = setup();
    const id = createOrder(app, 3000);
    createCoupon(app, { code: "HUGE", type: "FIXED", value: 5000 });
    const res = app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "HUGE" });
    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({ discountCents: 3000, finalAmountCents: 0 });
  });

  it("records the redemption on the coupon", () => {
    const app = setup();
    const id = createOrder(app, 12000);
    createCoupon(app, { code: "SAVE20", type: "FIXED", value: 2000 });
    app.request("POST", `/orders/${id}/apply-coupon`, { couponCode: "SAVE20" });
    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 1 });
  });
});

